  __m512i sc2 = _mm512_unpackhi_epi32( sb0, sb2 );
  __m512i sc3 = _mm512_unpackhi_epi32( sb1, sb3 );
  __m512i sc4 = _mm512_unpacklo_epi32( sb4, sb6 );
  __m512i sc5 = _mm512_unpacklo_epi32( sb5, sb7 );
  __m512i sc6 = _mm512_unpackhi_epi32( sb4, sb6 );
  __m512i sc7 = _mm512_unpackhi_epi32( sb5, sb7 );
  __m512i sc8 = _mm512_unpacklo_epi32( sb8, sba );
  __m512i sc9 = _mm512_unpacklo_epi32( sb9, sbb );
  __m512i sca = _mm512_unpackhi_epi32( sb8, sba );
  __m512i scb = _mm512_unpackhi_epi32( sb9, sbb );
  __m512i scc = _mm512_unpacklo_epi32( sbc, sbe );
  __m512i scd = _mm512_unpacklo_epi32( sbd, sbf );
  __m512i sce = _mm512_unpackhi_epi32( sbc, sbe );
  __m512i scf = _mm512_unpackhi_epi32( sbd, sbf );
  __m512i o0 = _mm512_unpacklo_epi32( sc0, sc1 );
  __m512i o1 = _mm512_unpackhi_epi32( sc0, sc1 );
