  __m512i o3 = _mm512_unpackhi_epi32( sc2, sc3 );
  __m512i o4 = _mm512_unpacklo_epi32( sc4, sc5 );
  __m512i o5 = _mm512_unpackhi_epi32( sc4, sc5 );
  __m512i o6 = _mm512_unpacklo_epi32( sc6, sc7 );
  __m512i o7 = _mm512_unpackhi_epi32( sc6, sc7 );
  __m512i o8 = _mm512_unpacklo_epi32( sc8, sc9 );
  __m512i o9 = _mm512_unpackhi_epi32( sc8, sc9 );
