  __m512i xa9 = _mm512_shuffle_i32x4( d9, dd, 0x88 );
  __m512i xaa = _mm512_shuffle_i32x4( da, de, 0x88 );
  __m512i xab = _mm512_shuffle_i32x4( db, df, 0x88 );
  __m512i xac = _mm512_shuffle_i32x4( d8, dc, 0xdd );
  __m512i xad = _mm512_shuffle_i32x4( d9, dd, 0xdd );
  __m512i xae = _mm512_shuffle_i32x4( da, de, 0xdd );
  __m512i xaf = _mm512_shuffle_i32x4( db, df, 0xdd );
  __m512i xb0 = _mm512_shuffle_i32x4( xa0, xa8, 0x88 );
  __m512i xb1 = _mm512_shuffle_i32x4( xa1, xa9, 0x88 );
  __m512i xb2 = _mm512_shuffle_i32x4( xa2, xaa, 0x88 );
  __m512i xb3 = _mm512_shuffle_i32x4( xa3, xab, 0x88 );
  __m512i xb4 = _mm512_shuffle_i32x4( xa4, xac, 0x88 );
  __m512i xb5 = _mm512_shuffle_i32x4( xa5, xad, 0x88 );
  __m512i xb6 = _mm512_shuffle_i32x4( xa6, xae, 0x88 );
  __m512i xb7 = _mm512_shuffle_i32x4( xa7, xaf, 0x88 );
  __m512i xb8 = _mm512_shuffle_i32x4( xa0, xa8, 0xdd );
  __m512i xb9 = _mm512_shuffle_i32x4( xa1, xa9, 0xdd );
  __m512i xba = _mm512_shuffle_i32x4( xa2, xaa, 0xdd );
  __m512i xbb = _mm512_shuffle_i32x4( xa3, xab, 0xdd );
  __m512i xbc = _mm512_shuffle_i32x4( xa4, xac, 0xdd );
  __m512i xbd = _mm512_shuffle_i32x4( xa5, xad, 0xdd );
  __m512i xbe = _mm512_shuffle_i32x4( xa6, xae, 0xdd );
  __m512i xbf = _mm512_shuffle_i32x4( xa7, xaf, 0xdd );
