  __m512i xcb = _mm512_unpackhi_epi32( xb9, xbb );
  __m512i xcc = _mm512_unpacklo_epi32( xbc, xbe );
  __m512i xcd = _mm512_unpacklo_epi32( xbd, xbf );
  __m512i xce = _mm512_unpackhi_epi32( xbc, xbe );
  __m512i xcf = _mm512_unpackhi_epi32( xbd, xbf );
