  v0 = _mm512_add_epi32( v0, v4 ); v1 = _mm512_add_epi32( v1, v5 ); v2 = _mm512_add_epi32( v2, v6 ); v3 = _mm512_add_epi32( v3, v7 );
  w0 = _mm512_add_epi32( w0, w4 ); w1 = _mm512_add_epi32( w1, w5 ); w2 = _mm512_add_epi32( w2, w6 ); w3 = _mm512_add_epi32( w3, w7 );
  vc = _mm512_xor_si512( vc, v0 ); vd = _mm512_xor_si512( vd, v1 ); ve = _mm512_xor_si512( ve, v2 ); vf = _mm512_xor_si512( vf, v3 );
  wc = _mm512_xor_si512( wc, w0 ); wd = _mm512_xor_si512( wd, w1 ); we = _mm512_xor_si512( we, w2 ); wf = _mm512_xor_si512( wf, w3 );
  vc = _mm512_ror_epi32( vc, 16 ); vd = _mm512_ror_epi32( vd, 16 ); ve = _mm512_ror_epi32( ve, 16 ); vf = _mm512_ror_epi32( vf, 16 );
  wc = _mm512_ror_epi32( wc, 16 ); wd = _mm512_ror_epi32( wd, 16 ); we = _mm512_ror_epi32( we, 16 ); wf = _mm512_ror_epi32( wf, 16 );
  v8 = _mm512_add_epi32( v8, vc ); v9 = _mm512_add_epi32( v9, vd ); va = _mm512_add_epi32( va, ve ); vb = _mm512_add_epi32( vb, vf );
  w8 = _mm512_add_epi32( w8, wc ); w9 = _mm512_add_epi32( w9, wd ); wa = _mm512_add_epi32( wa, we ); wb = _mm512_add_epi32( wb, wf );
  v4 = _mm512_xor_si512( v4, v8 ); v5 = _mm512_xor_si512( v5, v9 ); v6 = _mm512_xor_si512( v6, va ); v7 = _mm512_xor_si512( v7, vb );
  w4 = _mm512_xor_si512( w4, w8 ); w5 = _mm512_xor_si512( w5, w9 ); w6 = _mm512_xor_si512( w6, wa ); w7 = _mm512_xor_si512( w7, wb );
