  wf = _mm512_xor_si512( wf, w0 ); wc = _mm512_xor_si512( wc, w1 ); wd = _mm512_xor_si512( wd, w2 ); we = _mm512_xor_si512( we, w3 );
  vf = _mm512_ror_epi32( vf, 16 ); vc = _mm512_ror_epi32( vc, 16 ); vd = _mm512_ror_epi32( vd, 16 ); ve = _mm512_ror_epi32( ve, 16 );
  wf = _mm512_ror_epi32( wf, 16 ); wc = _mm512_ror_epi32( wc, 16 ); wd = _mm512_ror_epi32( wd, 16 ); we = _mm512_ror_epi32( we, 16 );
  va = _mm512_add_epi32( va, vf ); vb = _mm512_add_epi32( vb, vc ); v8 = _mm512_add_epi32( v8, vd ); v9 = _mm512_add_epi32( v9, ve );
  wa = _mm512_add_epi32( wa, wf ); wb = _mm512_add_epi32( wb, wc ); w8 = _mm512_add_epi32( w8, wd ); w9 = _mm512_add_epi32( w9, we );
  v5 = _mm512_xor_si512( v5, va ); v6 = _mm512_xor_si512( v6, vb ); v7 = _mm512_xor_si512( v7, v8 ); v4 = _mm512_xor_si512( v4, v9 );
  w5 = _mm512_xor_si512( w5, wa ); w6 = _mm512_xor_si512( w6, wb ); w7 = _mm512_xor_si512( w7, w8 ); w4 = _mm512_xor_si512( w4, w9 );
