  w0 = _mm512_add_epi32( w0, m[9] ); w1 = _mm512_add_epi32( w1, m[11] ); w2 = _mm512_add_epi32( w2, m[13] ); w3 = _mm512_add_epi32( w3, m[15] );
  v0 = _mm512_add_epi32( v0, v5 ); v1 = _mm512_add_epi32( v1, v6 ); v2 = _mm512_add_epi32( v2, v7 ); v3 = _mm512_add_epi32( v3, v4 );
