  /* round 1 */
  v0 = _mm512_add_epi32( v0, m[2] ); v1 = _mm512_add_epi32( v1, m[3] ); v2 = _mm512_add_epi32( v2, m[7] ); v3 = _mm512_add_epi32( v3, m[4] );
