  R->nb    = _mm256_set_epi32( (int)ops->nb[ base+1UL ], (int)ops->nb[ base+1UL ], (int)ops->nb[ base+1UL ], (int)ops->nb[ base+1UL ], (int)ops->nb[ base+0UL ], (int)ops->nb[ base+0UL ], (int)ops->nb[ base+0UL ], (int)ops->nb[ base+0UL ] );
